INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(40600, 0, 406, 0, 0, 0, 'Stonetalon Mountains', 'The Stonetalon Mountains rise west of the Barrens and south of Ashenvale, a range of forested peaks, deep canyons and mountain lakes, and both tauren and night elves have long held its great peak sacred. In the Third War, Jaina Proudmoore and Thrall each came to the caverns of Stonetalon Peak seeking the Oracle, and there the prophet Medivh urged orc and human to set aside old hatreds and stand together against the Burning Legion. Today the mountains are wounded. The Venture Company is stripping Windshear Crag of its forests, and the fires of its machines left the Charred Vale a blackened ruin of raging elementals and Bloodfury harpies. The spirits of the land cry out in pain, and both the Horde and the night elves have heard them. The Horde holds Sun Rock Retreat and the troll camp of Malaka''jin, while the night elves keep a small outpost on Stonetalon Peak beside the barrow of the Talon Den. Grimtotem tauren prowl the southeastern valleys, spiders haunt the Webwinder Path, and kobolds dig deep beneath Boulderslide Ravine.', 'warcraft.wiki.gg/wiki/Stonetalon_Mountains (sacred to tauren and night elves; Third War, Stonetalon Peak caverns, Oracle/Medivh, Alliance and Horde briefly united); warcraft.wiki.gg/wiki/Stonetalon_Peak (Jaina''s expedition and Thrall at the peak caverns); quest 1061 and 1062 descriptions (spirits angered, deforestation); quest 1057 description (Charred Vale set afire by industrialists); quest 1083 description (elementals released); zone_areas: Sun Rock Retreat, Malaka''jin, Stonetalon Peak, Talon Den, Grimtotem Post, Webwinder Path, Boulderslide Ravine spawns; warcraft.wiki.gg/wiki/Stonetalon_Mountains (Stonetalon Peak sacred to night elves and tauren; Oracle; Alliance and Horde temporarily united in the peak caverns)'),
(40601, 1, 406, 1, 0, 0, 'Greatwood Vale', 'The Greatwood Vale lies in the southeast of the mountains, where the road running west from the Crossroads climbs out of the Barrens. The Horde shaman Seereth Stonebreak keeps her camp near its edge, at the border of the two lands, and from there the way leads on to the northwest toward the logging grounds of Windshear Crag. The vale is not safe. Grimtotem mercenaries and ruffians roam its woods in great numbers, with brutes and sorcerers among them. Close to the troll camp of Malaka''jin, night elves sit caged in the vale as prisoners of the witch doctor Jin''Zil.', 'quest 1061 description (road west of the Crossroads, camped near the Greatwood Vale); quest 1062 and 1068 descriptions (Windshear Crag northwest beyond the Greatwood Vale); zone_areas area 469: Grimtotem Mercenary 32, Ruffian 15, Brute 5, Sorcerer 2, Prisoner of Jin''Zil 2; posarea: Seereth Stonebreak stands just inside the Barrens (area 17) at the border; quest 1058 description (three little cages for three little elves)'),
(40602, 1, 406, 2, 0, 0, 'Malaka''jin', 'Malaka''jin is a small troll camp at the base of the mountains, in the far southeast near the Barrens. Its people live well off the hunting in these hills, though lately spiders have been creeping into the camp by night to steal their kills, and Xen''Zilla wants the beasts thinned. In his cave at the camp, the witch doctor Jin''Zil keeps caged night elves and bubbling cauldrons of his own brews. Ken''zigla prepares healing draughts for wounded Horde soldiers as far off as Camp Taurajo, and Darn Talongrip sends willing recruits north to join the Horde campaign in Ashenvale.', 'quest 6461 description (trolls prosper from hunting; spiders raid camps at night to steal the hunt); quest 1510 description (healing draught from the trolls at Malaka''jin at the base of the Stonetalon Mountains); quest 1511 description (Ken''zigla''s draught to Logmar at Camp Taurajo); quest 6542 description (Darn Talongrip, Kadrak, Ashenvale campaign); quest 1058 description; creature_text 3995 (cauldron); zone_areas area 2539: Jin''Zil, Xen''Zilla, Ken''zigla, Darn Talongrip, Denni''ka, Prisoner of Jin''Zil; CreatureDisplayInfo 4105 (Ken''zigla: troll male model)'),
(40603, 1, 406, 3, 0, 0, 'Camp Aparaje', 'Camp Aparaje was a small tauren village in the southeastern hills of Stonetalon, home to Makaba Flathoof and his daughter Kaya. The Grimtotem fell upon it, led by Grundig Darkcloud of the post further up the path, and killed nearly everyone. Makaba slew all the raiders he could before he barely escaped with his life, and he now waits on the edge of the mountains by the Barrens, sure his daughter was lost in the attack. Grimtotem ruffians and mercenaries still pick through the abandoned camp. For those who know these trails, though, Aparaje remains a landmark on the road home.', 'warcraft.wiki.gg/wiki/Camp_Aparaje (tauren village, Makaba and Kaya lived there, attacked from Grimtotem Post under Grundig Darkcloud); quest 6548 description (Grimtotem raided my village, killed most everyone, I barely escaped); quest 6629 description (Grimtotem Post further up the path to the west); quest 6401 description (we had thought she was lost); quest 6523 description (Kaya: escort me to Camp Aparaje, from there I know my way); zone_areas area 2538: Grimtotem Ruffian 2, Grimtotem Mercenary 1'),
(40604, 1, 406, 4, 0, 0, 'Grimtotem Post', 'Grimtotem Post is a camp of the Grimtotem tribe in the southeastern Stonetalon Mountains, a little further up the path beyond Camp Aparaje. Brutes stand guard and sorcerers work their magic here, and the post is commanded by Grundig Darkcloud, who led the brutal raid that destroyed Aparaje, with his own band of brutes close about him. A tauren called Gorehoof the Black roams the camp as well. Not all of Aparaje''s people died in that raid. Makaba Flathoof''s daughter Kaya was taken alive, and she is held captive at the post, waiting for the chance to slip away.', 'quest 6629 description (Grundig Darkcloud and his personal band of brutes, led the attack, Grimtotem Post up the path to the west); zone_areas area 2537: Grimtotem Brute 19, Grimtotem Sorcerer 15, Kaya Flathoof 11856, Grundig Darkcloud 11858, Gorehoof the Black 11914; quest 6523 description (Thank you for rescuing me, before they discover I am free); creature_text 11856; CreatureDisplayInfo 10225 (Gorehoof the Black: tauren male model)'),
(40605, 1, 406, 5, 0, 0, 'The Webwinder Path', 'The Webwinder Path is the long road that winds north from the southern valleys through the heart of the mountains, toward Sun Rock Retreat and Windshear Crag. It is named well. Deepmoss spiders, creepers and venomspitters, hunt along its length, and travelers who walk it by night risk the fangs of Besseleth, the great spider of nearby Sishir Canyon, whose bounty notice is posted beside the road. On a rise overlooking the valley that leads into Windshear Crag, the night elf Kaela Shadowspear and her gnome companion Gaxim Rustfizzle have made their camp, plotting against the Venture Company.', 'zone_areas area 1076: Deepmoss Creeper 12, Deepmoss Venomspitter 7, Gaxim Rustfizzle, Kaela Shadowspear, Wanted Poster: Besseleth 177904; quest 6284 description and request text (Besseleth, travelers on Webwinder Path at night); quest 1070 description (Kaela overlooking the valley entering Windshear Crag); quest 1071 description (Windshear Crag to the east); warcraft.wiki.gg/wiki/Kaela_Shadowspear (night elf quest giver, camp southwest of Windshear Crag; not titled Sentinel)'),
(40606, 1, 406, 6, 0, 0, 'Sishir Canyon', 'Sishir Canyon opens west of the Webwinder Path, and it belongs to the spiders. Besseleth and her eight-legged brood have claimed it as their webbed lair, and the canyon floor is thick with deepmoss creepers, webspinners and venomspitters among clusters of eggs. Besseleth is an old predator of these parts who hunts the road by night, and she once caught Maggran Earthbinder of Sun Rock Retreat with her two-foot fang. A goblin trader in Ratchet pays well for deepmoss eggs, now prized for omelettes in Booty Bay, though even he warns that gathering them in Sishir is not for the weak of stomach.', 'Wanted Poster quest 6284 description (Sishir Canyon west of here, Besseleth and her eight-legged children, webbed lair); quest 6284 request and reward text (old predator, two-foot fang, Maggran wounded); zone_areas area 2541: Deepmoss Venomspitter 15, Creeper 9, Webspinner 5, Deepmoss Eggs, Besseleth 11921; quest 1069 description (Mebok Mizzyrix of Ratchet, omelette fad in Booty Bay, Sishir Canyon weak stomach)'),
(40607, 1, 406, 7, 0, 0, 'Boulderslide Ravine', 'Southeast of Sun Rock Retreat, Boulderslide Ravine cuts into the mountains, and at its end a deep cavern runs far beneath the stone. The Gogger kobolds have claimed it, rock keepers, geomancers and stonepounders who mine a rare crystal called resonite with frantic haste and shriek at anyone who reaches for their candles. The shaman Mor''rogal found that the crystals carry a trace of earthen magic, and the truth lay at the bottom of the cave: a resonite cask in which an earthen named Goggeroc slumbers. The earthen were made by the titans to shape the land itself, and the kobolds may have dug too deep.', 'quest 6421 description and reward text (southeast of Sun Rock, deep cave, kobolds frantically mining resonite, earthen magic, earthen created by the titans to shape the land); quest 6481 description (resonite cask houses a slumbering earthen named Goggeroc); zone_areas area 2540: Gogger Rock Keeper, Geomancer, Stonepounder, Resonite Crystal; Resonite Cask 178145; creature_text 11915/11917 (You no take candle)'),
(40608, 1, 406, 8, 0, 0, 'Sun Rock Retreat', 'Sun Rock Retreat is the Horde''s stronghold in the Stonetalon Mountains, a village of tauren and orcs tucked among the peaks south of Mirkfallon Lake and guarded by Stonetalon grunts. Its leader, the veteran Maggran Earthbinder, was sent here by Cairne Bloodhoof himself. Tammra Windfield calls on the Earthmother to help the scorched land grow again, the shaman Mor''rogal senses something evil stirring beneath the mountains, and Tsunaman serves the Tribunal of the Tides, waging the ancient war of water against fire in the Charred Vale. An inn and a wind rider post serve travelers, and at the edge of the village the mage Braelyn Firehand pursues a darker purpose of her own.', 'warcraft.wiki.gg/wiki/Sun_Rock_Retreat (Horde village in central Stonetalon, among peaks south of Mirkfallon Lake, orc and tauren forces); zone_areas area 460: Stonetalon Grunt 14, Maggran, Tammra, Mor''rogal, Tsunaman, Braelyn, Innkeeper Jayka, Tharm; npc_text 5443 (Cairne assigned me to Sun Rock Retreat); quest 6301, 6421, 6393, 1087 descriptions; warcraft.wiki.gg/wiki/Braelyn_Firehand (mage, quest giver at Sun Rock Retreat, removed in 4.0.3a)'),
(40609, 1, 406, 9, 0, 0, 'Mirkfallon Lake', 'Mirkfallon Lake lies north of Sun Rock Retreat, its shores the home of the Pridewing wyverns. Consorts, skyhunters and soarers nest about the water, a great patriarch among them, and a wyvern called Sorrow Wing hunts the shore. Sources in Theramore claim the orcs gather pridewing venom here for their assassins, and the Sentinels of Astranaar have sent fighters south to deny them the source. The lake also holds gentler gifts. Gaea seeds, found nowhere else in the mountains, lie along the water''s edge, and the tauren of Sun Rock gather them in the hope of restoring Stonetalon''s lost forests.', 'zone_areas area 464: Pridewing Wyvern 14, Consort 10, Soarer 2, Skyhunter, Patriarch 4015, Sorrow Wing 5928, Gaea Seed 177926 x12; quest 1134 description and reward text (Shindrell of Astranaar; Theramore sources claim orcs collect pridewing venom near Mirkfallon Lake for assassins); quest 6301 description (Gaea seeds only found in Stonetalon, north of Sun Rock at Mirkfallon Lake near the water''s edge); quest 6381 completion text (restoring Stonetalon to a lush forest)'),
(40610, 1, 406, 10, 0, 0, 'The Charred Vale', 'The Charred Vale in the southwest of the mountains was once a verdant forest. The Venture Company set it ablaze and turned its machines of destruction upon it, and in doing so loosed raging spirits of flame and stone. The treants of the vale seem to have driven the goblins back, but even these guardians were corrupted, some perhaps by the weapons the goblins used in their retreat, and blackened ancients now lumber through the ash. The Bloodfury harpies have since made the vale their stronghold, barring the druids who would heal it, while scorched basilisks and chimaeras hunt the burned slopes. The road south to Desolace runs through it.', 'quest 1844 description (once verdant, now defiled and ashen); quest 1083 description (set the forest aflame, inventions of destruction, released elementals of flame, stone and rage); quest 1084 description (treants drove the Venture Co. back, became corrupt, possibly from weapons used during the retreat); quest 1057 description (Bloodfuries refuse passage to begin regrowth); zone_areas area 465: Bloodfury harpies, Scorched Basilisk, Chimaera Matriarch, Charred/Blackened/Vengeful Ancient, Burning Destroyer, Enraged Stone Spirit; quest 5361 description (Charred Vale, then south into Desolace)'),
(40611, 1, 406, 11, 0, 0, 'Windshear Crag', 'Windshear Crag is a broad valley in the east of the mountains, and it is where the Venture Company''s greed is laid bare. Loggers, deforesters and operators swarm a landscape of stumps and fouled water, and the company''s lumber mill stands south of Cragpool Lake. Two great shredders marked XT:4 and XT:9 fell trees faster than the spirits can bear, and wagons of explosives wait along the trails. Kobold diggers toil for the company here too, and deepmoss spiders lay their eggs under what trees remain. On the crag''s western edge, the goblin Ziz Fizziks, fired when a gnome took charge of the operation, has set up camp and now works against his former employers.', 'warcraft.wiki.gg/wiki/Windshear_Crag (massive logging, stumps and polluted water); zone_areas area 461: Venture Co. Logger 49, Deforester 29, Operator 17, XT:4, XT:9, Explosives Wagons, Deepmoss Eggs, Ziz Fizziks; quest 1068 description (XT:4 and XT:9 felling trees with impossible speed); quest 1079 description (lumber mill south of Cragpool Lake); quest 1069 description (eggs clustered under what trees remain); quest 1090 and 1483 descriptions (Gerenzo took over and fired Ziz; Ziz at the western edge of Windshear Crag); zone_areas area 461: Windshear Digger 46, Overlord 9, Geomancer 5 (kobold models, CreatureDisplayInfo 2153, 511, 163)'),
(40612, 1, 406, 12, 0, 0, 'Windshear Mine', 'The Windshear Mine sits at the far eastern end of Windshear Crag, where the Blackwolf River ends. The Venture Company works it with kobolds in its employ, diggers, geomancers and overlords. On Gerenzo Wrenchwhistle''s orders, large amounts of a strange gold-green ore are being hauled from its depths, for a purpose none of the miners has learned. Among them is Piznik, once the second most important goblin at the site, sent down to the tunnels when Gerenzo took over and now quietly spying for his old boss. The overlords grow wary of him all the same. The company keeps some of its letters here, deep inside.', 'quest 1080 description (Windshear Mine at the east end of Windshear Crag, Venture Co. letters); warcraft.wiki.gg/wiki/Windshear_Mine (Venture Company employed kobolds to mine; at the end of the Blackwolf River); quest 1090 description (Piznik second most important, sent down to the mines, gold-green ore, gather information for Ziz); creature_text 4004 (Overlord: Piznik, I knew we shouldn''t have let you stick around); DB: Windshear Digger, Geomancer, Overlord; Piznik 4276 and Venture Co. Documents 19603 at the mine near 960..990,-260..-390; CreatureDisplayInfo 2153, 163, 511 (Windshear Digger, Geomancer, Overlord: kobold models); 7157 (Piznik: goblin); WMOAreaTable rows 19186 to 19210 (WMO 996, area 2160)'),
(40613, 1, 406, 13, 0, 0, 'Cragpool Lake', 'Cragpool Lake lies in the north of Windshear Crag, and the Venture Company has crowded its shores. Oil spills slick the water, while engineers, machine smiths and builders keep the company''s machines running along the banks, and a goblin named Nizzik sells Venture armor to any customer with coin. Far above the lake, up beside the great water wheel, Gerenzo Wrenchwhistle keeps watch over the entire site from his high platform. From the lake the Blackwolf River runs out through the crag, and travelers bound for Stonetalon Peak skirt the water before turning north up the steep slopes.', 'zone_areas area 463: Oil Spill, Venture Co. Engineer, Machine Smith, Builder, Logger, Nizzik <Venture Armor Salesman> 4085 (faction 35), Gerenzo Wrenchwhistle 4202; quest 1096 description (northeast of here, far above Cragpool Lake, near the water wheel, Gerenzo watches over the entire site); quest 1079 description (lumber mill south of Cragpool Lake); quest 1056 description (southwest past Cragpool Lake and then north up the steep slope to Stonetalon Peak); warcraft.wiki.gg/wiki/Blackwolf_River (runs through Windshear Crag from Cragpool Lake); creature positions: Gerenzo 1606,97 and Nizzik 1608,184 lie north of Ziz (878,365) and the mine (986,-390)'),
(40614, 1, 406, 14, 0, 0, 'Blackwolf River', 'The Blackwolf River runs out of Cragpool Lake and down through Windshear Crag to the mine at its far end, and its waters have been fouled by the Venture Company''s logging of the valley. The company''s crews have stripped the banks bare. Loggers, deforesters and operators work the riverside, kobold geomancers among them, oil leaks into the current, and a wagon of explosives waits nearby. Two hard bosses drive the work here: Foreman Rigger, a human, and Taskmaster Whipfang, a gnoll.', 'zone_areas area 636: Venture Co. Logger 14, Deforester 7, Operator 5, Oil Spill 3, Explosives Wagon, Foreman Rigger 5931, Taskmaster Whipfang 5932; warcraft.wiki.gg/wiki/Windshear_Mine (mine at the end of the Blackwolf River); warcraft.wiki.gg/wiki/Blackwolf_River (from Cragpool Lake through Windshear Crag; heavily polluted by Venture Company deforestation); CreatureDisplayInfo 4600 (Rigger: human male), 487 (Whipfang: gnoll)'),
(40615, 1, 406, 15, 0, 0, 'The Talondeep Path', 'The Talondeep Path is a long tunnel bored through the mountains, joining Windshear Crag to southern Ashenvale not far from Mystral Lake. It is a main road between Stonetalon and the forest: night elves bound for Stonetalon Peak travel it, and Horde caravans running between the mountains and Splintertree Post depend on it, so that trouble at Mystral Lake can bring them to a standstill. Deepmoss spiders lurk in its shadows and lay their eggs in the dark. Near its Stonetalon mouth waits the tauren shaman Braug Dimspirit, a sage of great wisdom who tests the seekers sent to him on their knowledge of the world''s lore.', 'quest 1056 description (tunnel near Mystral Lake leads to Windshear Crag); quest 25 description (transports between Ashenvale and Stonetalon via Talondeep Path); zone_areas area 1277: Deepmoss Webspinner, Braug Dimspirit 4489; quest 1152 description and reward text (Braug, shaman of great wisdom, near the tunnel; Dorn; goblins rape the land, night elves point fingers at the younger races); npc_text 5820 (question on the Aspects); quest 25 description (caravans between Splintertree Post and Stonetalon at a standstill); zone_areas area 1277: Deepmoss Eggs 19541, 19542'),
(40616, 1, 406, 16, 0, 0, 'Stonetalon Peak', 'Stonetalon Peak crowns the far northwest of the mountains, a high forested valley that local peoples have long held sacred. Ruins of an ancient temple of Queen Azshara still stand here. The night elves keep a small outpost here with an inn and a hippogryph roost, where Keeper Albagorm watches over the land, and the Sons and Daughters of Cenarius and their botanists tend the woods, while sap beasts, twilight runners and fey dragons roam among the trees. In the Third War, Jaina Proudmoore''s expedition camped by the caverns of the peak, and Thrall came there too in search of the Oracle. More recently, the druids hid Keeper Ordanus here, before spiriting him away to Ashenvale.', 'warcraft.wiki.gg/wiki/Stonetalon_Peak (northwestern end, forested valley, sacred, temple of Queen Azshara, Third War Jaina and Thrall at the caverns, druids maintain it); quest 1088 description and request text (our ancient temple of Azshara, sacred ruins; they spirited Ordanus away from the peak); quest 1087 description (ilk of Cenarius and kaldorei druids at the peak); zone_areas area 467: Keeper Albagorm, Innkeeper Faralia, Teloren hippogryph master, Son/Daughter of Cenarius, Cenarion Botanist, Sap Beast, Twilight Runner, Fey Dragon, Wily Fey Dragon'),
(40617, 1, 406, 17, 0, 0, 'The Talon Den', 'The Talon Den is a barrow den of the druids on Stonetalon Peak. Cenarion druids and caretakers walk its halls beside the Mirkfallon dryads, and an ancient keeper of the grove, Gatekeeper Kordurus, stands among them. Here the druids keep many items of power, and to guard them they devised an intricate scheme: a gatekeeper''s key hidden in a lantern at the entrance opens caches scattered through the den, and only the contents of all three can unseal the great hoard deeper within. The dryad Rynthariel holds the den''s keys, and a night elf called Brother Ravenoak prowls its depths.', 'warcraft.wiki.gg/wiki/Talon_Den (barrow den on Stonetalon Peak; dryads, caretakers, keepers; Kordurus, Rynthariel, Ravenoak); quest 1089 description (the druids built the Talon Den, powerful items, complex scheme, Gatekeeper''s Key in a lantern at the entrance, caches, hoard in a central area); quest 1089 completion text (three keyholes); zone_areas area 468: Cenarion Druid 16, Cenarion Caretaker 7, Mirkfallon Dryad 6, Gatekeeper Kordurus, Rynthariel the Keymaster, Brother Ravenoak, Gatekeeper''s Hold, Druids'' Cache, Barrow Cache; quest 3514 description (scheming dryad Rynthariel, Keymaster); CreatureDisplayInfo 2432 (Kordurus: keeper of the grove model), 4599 (Ravenoak: night elf male); gameobject 19599 Talon Den Hoard at 2562,1947 (posarea 467, past the den''s caches)'),
(40618, 2, 406, 1, 2, 0, 'Seereth Stonebreak', 'Seereth Stonebreak is a promising shaman of the Horde, sent to Stonetalon when the land cried out. She camps where the road from the Crossroads meets the mountains, near the Greatwood Vale, and to her the spirit of Stonetalon weeps from its peaks, its rivers and its severed trees. Shamans can hear the pleas of such spirits because their magic is kin to the natural magic of the druids, she says, though many of the whispers are lost to her. One vision came clear: two man-shaped machines felling trees with impossible speed. Even so, she fears the spirits may never be soothed, and worse may follow.', 'quest 1061 description (promising shaman of the Horde, sent to Stonetalon, camped near the Greatwood Vale); quest_greeting 4049 (spirit of Stonetalon weeps, peaks, rivers, severed dying trees); quest 1068 description and reward text (relation between shamanic and druidic magic, whisperings lost, vision of XT:4 and XT:9; fears what lies ahead); creature_text 4049 (I fear we may never soothe them)'),
(40619, 2, 406, 2, 2, 0, 'Maggran Earthbinder', 'Maggran Earthbinder leads Sun Rock Retreat, an old tauren warrior who admits that age and countless battles have hardened his skin and his soul. He believes that is why Cairne Bloodhoof gave him this post, where gentle winds and warm sun ease his pain. Maggran takes the tauren duty as protectors of the land seriously. He holds the Bloodfury harpies of the Charred Vale to be the source of the harpies spreading across Kalimdor and wants their queen, Bloodfury Ripper, dead, and he has put a bounty on the spider Besseleth, whose fang once wounded him. With the Ripper slain, he feels his anger begin to leave him.', 'npc_text 5443 (age and battles hardened skin and soul; Cairne assigned me; gentle winds and warm sun); quest 6282 description (tauren take pride as protector of these lands; Bloodfuries source of increasing harpies in Kalimdor); quest 6283 description and reward text (Bloodfury Ripper all but a queen; already I feel the anger leave me); quest 6284 request and reward text (bounty, Maggran wounded by Besseleth''s fang)'),
(40620, 2, 406, 3, 2, 0, 'Witch Doctor Jin''Zil', 'Jin''Zil is a troll witch doctor who lives in a cave at Malaka''jin, among bubbling cauldrons. He is an old friend of Darsok Swiftdagger of the Crossroads, and he still recalls the day his friend Rokhan went off with that crazy mok''nathal Rexxar to kill the elder sister of Serena Bloodfeather, so the news of Serena''s death pleases him well. His temper is gleeful and cruel. Three night elves sit caged near his camp, and for them he brews what he calls forest magic, out of sap from Stonetalon Peak, the whiskers of twilight runners, a fey dragon''s scale and as many courser eyes as he can get.', 'quest 1060 description and reward text (old friend of Darsok; letter; last of the Bloodfeathers; Rokhan went with that crazy mok''nathal to kill her older sister); barrens.json Serena Bloodfeather entry (Rexxar and Rokhan killed her sister); quest 1058 description, request and reward text (three cages, forest magic ingredients, eyes); creature_text 3995 (cauldron; feel the magic seep into the cave, my little elves)'),
(40621, 2, 406, 4, 2, 0, 'Braelyn Firehand', 'Braelyn Firehand is a mage who camps at Sun Rock Retreat, and she despises these mountains. The druids of Stonetalon Peak and the kin of Cenarius stifle the flow of magic far beyond their forests, and here, she says, channeling a spell is like drawing water with a bucket full of holes. Her master in Jaedenar will not let her return until her work is done. That work began at the peak, among the sacred ruins of what she calls her own people''s ancient temple of Azshara. When she feels magic rush back into her she exults in it, for to her life without its burning embrace is a pale mockery, and the kaldorei who spurn it are fools.', 'quest 1087 description and request text (hatred, stifle the flow of magic, master in Jaedenar, bucket full of holes); quest 1088 request and reward text (master bade me to the peak, sacred ruins of our ancient temple of Azshara; I knew Ordanus once, held himself above even the Highborne); zone_areas area 460: Braelyn Firehand; quest 1087 reward text (power so sweet; kaldorei foolish to spurn the gifts; pale mockery without its burning embrace); warcraft.wiki.gg/wiki/Braelyn_Firehand (mage; at Sun Rock Retreat)'),
(40622, 2, 406, 5, 1, 0, 'Keeper Albagorm', 'Keeper Albagorm watches over Stonetalon Peak for the night elves, and he mourns what greed has done to these sacred hills. When the forest spirits whisper to Faldreas Goeth''Shael in Astranaar, it is to Albagorm that the brave are sent, through the Talondeep Path and up the steep slopes past Cragpool Lake. His great hope is the Charred Vale. He means to restore it to the lush forest it once was, but first the Bloodfury harpies who bar the druids from the vale must be broken, and then the great forest spirits must be called to help, by a druid far to the south.', 'quest 1056 description and reward text (Faldreas has listened to the forest spirits; route via Talondeep Path, Cragpool Lake, steep slope); quest 1057 description and request text (protector of the forest spirits, greed destroyed sacred hills, Bloodfuries refuse passage, restore lush forest); quest 1059 description (Falfindel Waywarder can call forth great forest spirits); zone_areas area 467: Keeper Albagorm'),
(40623, 2, 406, 6, 1, 0, 'Kaela Shadowspear', 'Kaela Shadowspear is a night elf of Ashenvale, sent to Stonetalon by Sentinel Raene Wolfrunner to learn what was happening to the land, with a gnome mage assigned to accompany her. From her camp above the road into Windshear Crag she has spent most of her days fighting the Venture Company''s destruction. That a night elf and a gnome must work together shows how grave things are, she admits, but she asks others not to judge Gaxim too quickly. She still misses her homeland and her friend Tara Thenysil in Astranaar, and the first time she saw the Charred Vale, she nearly wept.', 'quest 1070 description and reward text (Sentinel Wolfrunner sent my friend Kaela; gnome mage along; how I miss her, my homeland and friends); quest 1085 description (night elf and gnome working together; most of my time putting an end to the destruction; do not judge Gaxim prematurely); quest 1083 request text (first time I saw the Charred Vale I almost wept); quest 1082 description (Tara Thenysil in Astranaar); warcraft.wiki.gg/wiki/Kaela_Shadowspear (night elf, affiliation Darnassus, not titled Sentinel)'),
(40624, 2, 406, 7, 1, 0, 'Gaxim Rustfizzle', 'Gaxim Rustfizzle is a gnome of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and he holds it as his duty to prove to the night elves that magic, mixtures and mechanisms together can save their forests. Swearing off magic entirely, he insists, will help no one. At Kaela Shadowspear''s side he wages a cheerful war of explosions on the Venture Company, herding goblin crews with carefully placed detonations along the mountains'' edges. His friends reach far: an old colleague in Tinker Town who brews volatile Nitromirglyceronium, and Collin Mauren of Stormwind''s mage quarter, who works him a spell for setting off a blast from afar.', 'quest 1071 description and reward text (Enlightened Assembly; my duty to show the night elves; high explosives to herd goblins along the mountains'' edges); quest 1085 reward text (swearing off magic completely won''t help the night elves); quest 1072 to 1074 (Lomac Gearstrip in Tinker Town, NG-5); quest 1075 to 1077 (Collin Mauren, mage quarter, remote detonation scroll)'),
(40625, 2, 406, 8, 0, 0, 'Ziz Fizziks', 'Ziz Fizziks was once an engineer of the Venture Company in Windshear Crag, until the company hired a gnome. The goblin was so appalled that he begged Sputtervalve of the Tinkers'' Union in Ratchet for a new job, and when Gerenzo Wrenchwhistle took over the site, Ziz was thrown out. He told his man Piznik to stay behind in the mine and spy. Now he camps on the crag''s western edge, eager to prove his loyalty to his new boss, though he admits a goblin''s honor is only worth so much. He would happily see Gerenzo dead, and he dreams of a post in the Union''s workshops in Gadgetzan or even Undermine.', 'quest 1483 description (Gerenzo hired, Ziz taken aback, pleaded with Sputtervalve for new employment, western edge of Windshear Crag); quest 1090 description (Gerenzo fired my boss Ziz; Ziz told me to stay and gather information); quest 1092 reward text (I did the right thing by telling Piznik to stay behind); quest 1093 description and request text (kicked out; Sputtervalve hired me; goblin''s honor); quest 1095 and 1096 reward text (no objections to eliminating Gerenzo; Tinkers'' Union workshops in Gadgetzan or Undermine)'),
(40626, 2, 406, 9, 0, 0, 'Gerenzo Wrenchwhistle', 'Gerenzo Wrenchwhistle is the gnome who runs the Venture Company''s operation in Windshear Crag, and he is not easy to look upon: his flesh seems to rot away, and he has grafted gears and metal onto his body and replaced limbs with machines. He was once one of the head engineers of Gnomeregan, working on its secret project, which ended by exploding in its makers'' faces. His hiring so appalled the goblin Ziz Fizziks that he left the company, and under Gerenzo the outfit built the Super Reaper 6000, a vast woodcutting machine. From a platform high above Cragpool Lake he watches the whole site, and some in Undermine want him gone.', 'quest 1096 description (flesh rotting, metal and gears grafted, limbs replaced; far above Cragpool Lake near the water wheel); quest 1095 description and reward text (trade princes disapprove of Razdunk consorting with Gerenzo; head engineer in Gnomeregan, secret project exploded in their faces); quest 1093 description (enormous woodcutting machine, Gerenzo wants Ziz dead); warcraft.wiki.gg/wiki/Gerenzo_Wrenchwhistle (leper gnome, built the Super Reaper 6000); creature_template 4202 faction 47 (hostile to both); warcraft.wiki.gg/wiki/Gerenzo_Wrenchwhistle (leper gnome)'),
(40627, 2, 406, 10, 2, 0, 'Rynthariel the Keymaster', 'Rynthariel is a dryad of the Talon Den on Stonetalon Peak, its Keymaster and, to the Horde, its leader. She sends Alliance runners across Horde lands in the Barrens, and when one of her scrolls was taken from a fallen courier and carried to Kadrak at the watch tower in the north, the Horde took it as an insult. Kadrak called her a scheming dryad and demanded more than her death: a Horde banner raised inside the den itself, so that the night elves would think twice before sending another runner through Horde territory.', 'quest 3514 description and reward text (scroll from that scheming dryad Rynthariel, Keymaster of the Talon Den; kill her and put up a Horde flag; fewer Alliance runners in the Barrens); quest 3513 (The Runed Scroll, dropped by Aean Swiftriver 5797, taken to the outpost near the Ashenvale border); creature_template 8518 faction 124 (friendly to the Alliance); zone_areas area 468: Rynthariel the Keymaster'),
(40628, 3, 406, 1, 2, 0, 'The Spirits of Stonetalon', 'The spirits of the Stonetalon Mountains are angered, for the goblins of the Venture Company and their servants are cutting and burning the forests. The land cried out, and in Orgrimmar the far seer Zor Lonetree heard. He sent help west from the Crossroads to the promising shaman Seereth Stonebreak, who had reported deforestation on a massive scale. She asked first for the answer the goblins understand best, violence, and loggers fell in Windshear Crag. Then a vision came to her of two man-shaped machines marked XT:4 and XT:9, cutting down trees with impossible speed, and these too were destroyed, soothing many of the spirits. Yet Seereth knew it was not enough. To truly tend the spirits, the tauren elders must be consulted, and the only one she knew by name was the aged Magatha on Elder Rise in Thunder Bluff. What the Elder Crone made of the plea is another tale.', 'quest 1061 description (spirits angered, land cried out, those who listen have heard, Seereth reports massive deforestation); quest 1062 description and reward text (show them in the language they understand, violence; wisdom of tauren elders); quest 1068 description and reward text (vision of XT:4 and XT:9, soothed many spirits); quest 1063 description (consult the tauren elders, only knows Magatha, very old, Elder Rise); orgrimmar.json Valley of Wisdom (Zor Lonetree, elder far seer)'),
(40629, 3, 406, 2, 2, 0, 'Cenarius'' Legacy', 'Braelyn Firehand came to Stonetalon at her master''s bidding, expecting nothing more than to slaughter the night elves who crawled over the ruined temple of Azshara on the peak. But the prize she was sent for had slipped away. First she wanted the flow of magic restored, and Horde blades cut down the Sons and Daughters of Cenarius and their botanists until she felt power flood back into her veins. Then her magic granted her true sight, and she found her quarry, Keeper Ordanus, hidden far off in Ashenvale. She wanted his head, and when it was brought to her she gloated over the arrogant keeper she had known long ago. Last, she revealed a secret wrung from one of the druids: how a key hidden at the entrance of the Talon Den could unlock the druids'' caches, and through them the hoard within.', 'quest 1087 description and reward text (master in Jaedenar; kill Sons and Daughters of Cenarius and botanists; power so sweet, the rushing flood); quest 1088 description, request and reward text (true sight; Raynewood, crossroads, eldest sons of the forest god; spirited away from the peak; master bade me to the peak; sacred ruins of our ancient temple of Azshara; I knew Ordanus once); quest 1089 description (extract some details from one of them; Gatekeeper''s Key in a lantern, caches, hoard); ashenvale.json Raynewood Retreat entry (Ordanus hiding at the top of the tree)'),
(40630, 3, 406, 3, 1, 0, 'On Guard in Stonetalon', 'Sentinel Tara Thenysil of Astranaar had heard nothing from her friend Kaela Shadowspear, sent into Stonetalon with a gnome mage at her side, and she sent someone to look. Kaela was alive, camped above the road into Windshear Crag, and her companion Gaxim Rustfizzle had a plan. It began with explosions. Goblin crews were driven back while Gaxim gathered his materials: volatile Nitromirglyceronium from an old colleague in Tinker Town, made from potions brought to his door, and a scroll of messaging from Collin Mauren in Stormwind, crafted with debris from a Westfall dust devil, so that the charges could be fired from afar. With wagons of dynamite as a distraction, the Venture Company''s engineering plans were stolen from the lumber mill and its letters from Windshear Mine. Kaela sent word home that the land might yet heal, and Thenysil sent the messenger on to Darnassus, where Tyrande Whisperwind herself offered her thanks.', 'quest 1070 description (Thenysil, Kaela, gnome mage); quest 1085 description; quest 1071 description and reward text; quests 1072, 1073, 1074 (Lomac Gearstrip, NG-5); quests 1075, 1076, 1077 (Collin Mauren, dust devil debris, scroll of messaging, remote explosive); quests 1079 and 1080 (plans from the lumber mill, letters from Windshear Mine); quest 1091 (Kaela''s Update); quest 1082 description (Gaxim and I are alive, well on our way to stopping the Venture Co. and healing the lands); quest 1081 description and reward text (Tyrande, gift of appreciation)'),
(40631, 3, 406, 4, 1, 0, 'Reclaiming the Charred Vale', 'In Astranaar, Faldreas Goeth''Shael listens to the spirits of the forest, and they told him of one brave enough to travel. He sent that traveler south through the Talondeep Path, across the ravaged Windshear Crag and up the steep slopes to Stonetalon Peak, where Keeper Albagorm waited. The keeper''s grief was for the Charred Vale, once forest, now ash, set afire by a greedy mechanized army of industrialists. The druids wished to begin its regrowth, but the Bloodfury harpies who had settled the burned vale would not let them pass. Harpies, ambushers, slayers and roguefeathers fell until the flock was badly broken. Albagorm knew they would regroup soon, and so he sent word far south, past the Barrens and into Thousand Needles, to the druid Falfindel Waywarder at the edge of Feralas, who has the power to call great forest spirits to help in the vale''s reclamation.', 'quest 1056 description and reward text (forest spirits tell me you are brave; route; Faldreas has listened to the forest spirits); quest 1057 description, request and reward text (set afire by the greedy mechanized army of industrialists; Bloodfuries refuse passage; restore the lush forest); quest 1059 description and reward text (Bloodfuries subdued but will regroup; Falfindel Waywarder at the border of Thousand Needles and Feralas, can call forth great forest spirits)'),
(40632, 3, 406, 5, 2, 0, 'The Seeds of Gaea', 'At Sun Rock Retreat, Tammra Windfield grieves for a land wrecked by industrial greed and endless war, and she holds that only the blessings of the Earthmother can cure such an injury. Her hope lies in the Gaea seed, found nowhere else but along the shores of Mirkfallon Lake. Once the seeds were gathered, she chanted over them, imbuing them with shamanic power so that even such small kernels of life might bloom. They were then carried west into the heart of the destruction, the Charred Vale, past harpies and raging fire spirits, and planted in mounds of fertile soil. Such seeds resist corruption, Tammra says, and will make a foothold for other life. In time the Venture Company will pack up its saws, the fire spirits will calm, the harpies will be pushed out by the land itself, and only then will Stonetalon truly know peace.', 'quest 6301 description and reward text (industrial greed and continuous war; blessings of the Earthmother; Gaea seeds only found at Mirkfallon Lake; imbue with shamanistic power; Tammra begins to chant); quest 6381 description, request and reward text (plant at the center of the destruction in the Charred Vale; harpies and fire elementals; resist corruption, foothold for other life; Venture Co. will pack up, fire spirits calm, harpies pushed out; then truly at peace); zone_areas: Gaea Seed 177926 at Mirkfallon Lake, Gaea Dirt Mound 177929 in the Charred Vale'),
(40633, 3, 406, 6, 0, 0, 'Gerenzo''s Orders', 'When the Venture Company hired the gnome Gerenzo Wrenchwhistle to run its Windshear Crag outfit, the goblin engineer Ziz Fizziks was so appalled he begged Sputtervalve of the Tinkers'' Union for a new job, and was soon thrown out. His man Piznik, sent down to the mines, stayed behind to spy. While patrols closed in, Piznik dug out a sample of the gold-green ore Gerenzo had ordered mined in bulk, then slipped away himself, and Ziz meant to send it to the engineers of Undermine, keeping a piece for himself. Next came the blueprints of the Super Reaper 6000, Gerenzo''s monstrous woodcutter, taken from a company operator and sealed with stolen documents for Sputtervalve in Ratchet. Sputtervalve answered with orders from higher up: the trade princes disapproved of Razdunk''s dealings with the gnome, and Director Riddlevox wanted Gerenzo removed. Gerenzo, once a head engineer of Gnomeregan, was slain on his platform above Cragpool Lake, and his mechanical arm carried back as proof.', 'quest 1483 description and reward text (Sputtervalve; Gerenzo hired; Ziz pleaded for new employment); quests 1090 and 1092 (Piznik, ore sample, watch for patrols, sneak out; engineers in Undermine; keep a piece for myself); creature_text 4276 and 4004 (escort lines); quests 1093 and 1094 (Super Reaper 6000 blueprints on an operator; sealed envelope with internal documents to Sputtervalve at Ratchet); quest 1095 description and reward text (trade princes, Razdunk, Riddlevox; Gerenzo head engineer in Gnomeregan); quest 1096 description and request text (above Cragpool Lake; mechanical arm as proof)'),
(40634, 3, 406, 7, 2, 0, 'The Fall of Camp Aparaje', 'Makaba Flathoof waits at the edge of the mountains by the Barrens, one of the very few who lived through the day the Grimtotem came to Camp Aparaje. He killed all he could before he fled, and now he asks only that more of them die: ruffians and mercenaries in the woods to the west, then the brutes of Grundig Darkcloud, who led the raid, at Grimtotem Post. Inside the post waited something Makaba never expected. His daughter Kaya, believed lost in the attack, was alive and a prisoner. Freed, she begged to be taken back to Camp Aparaje before her captors noticed, and Grimtotem brutes, ruffians and sorcerers struck again along the way. From the ruins of her village she knew the road home. Makaba sent the good news on to Sun Rock Retreat, to Kaya''s aunt Tammra Windfield, who could scarcely believe her niece still lived.', 'quest 6548 description and reward text (Grimtotem raided my village, killed most everyone, I killed all I could, barely escaped; just to the west); quest 6629 description (Grundig Darkcloud and his personal band of brutes, led the attack, Grimtotem Post); quest 6523 description (thank you for rescuing me, escort me to Camp Aparaje, from there I know my way, father Makaba); creature_text 11856 (Let''s go before they find out I''m free; Look out, we''re under attack; I know my way back from here); quest 6401 description and reward text (Kaya''s aunt Tammra at Sun Rock; we had thought she was lost; my niece Kaya is alive)'),
(40635, 3, 406, 8, 2, 0, 'Earthen Arise', 'The shaman Mor''rogal of Sun Rock Retreat could feel a tension in the air of Stonetalon, a sense that something evil lurked beneath the mountains. Southeast of the retreat, in a deep cave in Boulderslide Ravine, the Gogger kobolds were mining a rare crystal called resonite in a frenzy, and Mor''rogal wanted samples and word of what lay at the cave''s bottom. He half remembered a legend tied to resonite, and the crystals confirmed it: they bore a trace of earthen magic. The earthen were made by the titans to shape the very land, and at the bottom of the cave stood a resonite cask in which one of them, Goggeroc, lay sleeping. Mor''rogal feared what such a being might mean for all of Kalimdor. He enchanted a crystal to break the cask, knowing the earthen would be weak from his long slumber, and Goggeroc was slain while that weakness lasted.', 'quest 6421 description, request and reward text (tension, evil under the mountains, southeast cave, kobolds frantically mining Resonite, legend; trace of Earthen magic, created by the Titans to create the land, enchant the samples); quest 6481 description, request and reward text (Resonite cask houses slumbering Earthen Goggeroc; enchanted crystal to smash it; weak from slumber; what an Earthen would mean to Kalimdor); zone_areas area 2540 and Resonite Cask 178145');
